const input = (root: string, cards: Card[], maxRetryBatches: number): RunInput => ({ root, runId: "r1", branch: "morph/r1",
  deck: { cards, externalDependsOn: [] }, budget: { maxCards: 10, maxRetryBatches, deadline: 1e15 } });
